// The label designer's built-in icon library: component symbols and
// packages, connectors and terminals, screws by thread type with nuts,
// washers and inserts, and motion parts (bearings, belts, magnets…) — vector
// marks for bin labels.
// The catalogue (label-icons.json) is generated by
// scripts/import-label-icons.ts from the packs in assets/icon-packs and is
// already sanitised; it is loaded on demand when the picker opens.

export type LabelIcon = {
  // "<pack>/<set>/<name>", e.g. "screw/drives/torx".
  id: string;
  name: string;
  // Spec or standard, e.g. "2.50 mm" or "ISO 4762".
  detail: string;
  note: string;
  // Extra search terms, e.g. the short name "NTC" for "Thermistor".
  keywords: string;
  category: string;
  viewBox: [number, number, number, number];
  markup: string;
};

// The packs in library order, by the first segment of an icon's id.
export const ICON_PACKS = {
  component: "Components",
  connector: "Connectors",
  screw: "Screws & hardware",
  motion: "Motion",
} as const;
export type IconPack = keyof typeof ICON_PACKS;

export const iconPack = (icon: LabelIcon) => icon.id.split("/")[0] as IconPack;

export async function loadIcons(): Promise<LabelIcon[]> {
  return (await import("@/lib/label-icons.json")).default as LabelIcon[];
}

/**
 * Whether `id` is shaped like a catalogue id ("screw/drives/hex") — safe to
 * store and to put in a URL path. It may still name no icon.
 */
export function isIconId(id: string): boolean {
  return id.length <= 200 && /^[a-z0-9-]+(\/[a-z0-9-]+)+$/.test(id);
}

/** URL of an icon as a standalone SVG image (src/app/api/icons/[...id]). */
export const iconUrl = (id: string) => `/api/icons/${id}`;

/**
 * A catalogue icon as a standalone SVG document, for an <img> (a part's
 * thumbnail). The markup draws in currentColor, which is black in an image —
 * as on a label.
 */
export function iconSvgDocument(icon: Pick<LabelIcon, "viewBox" | "markup">): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${icon.viewBox.join(" ")}">${icon.markup}</svg>`;
}

/** Icons grouped by category, in catalogue order. */
export function groupIcons(icons: LabelIcon[]): { category: string; icons: LabelIcon[] }[] {
  const groups = new Map<string, LabelIcon[]>();
  for (const icon of icons) groups.set(icon.category, [...(groups.get(icon.category) ?? []), icon]);
  return [...groups].map(([category, list]) => ({ category, icons: list }));
}

/**
 * Icons matching every word of `query` in their name, short name, spec,
 * category, note or id — so "jst 2.0", "iso 4762", "ntc" and "nut" all find
 * something.
 */
export function searchIcons(icons: LabelIcon[], query: string): LabelIcon[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return icons;
  return icons.filter((icon) => {
    const haystack = `${icon.name} ${icon.keywords} ${icon.detail} ${icon.category} ${icon.note} ${icon.id}`.toLowerCase();
    return words.every((w) => haystack.includes(w));
  });
}
